w:r.w:t:
% a) FORMULACION DEL PVI Y DATOS DEL PROBLEMA clearvars; close all; clc; format long g;
% Parametros en las unidades exigidas por el enunciado. p.Qmax = 0.0060; % m^3/s p.Kv = 3.8e-4; % m^3/(s*kPa^(1/2)) p.Ch = 4.0e-4; % m^3/kPa p.rho = 900; % kg/m^3 p.cp = 2000; % J/(kg*K) p.Qgen = 45000; % W p.UA = 320; % W/K p.Tin = 18; % grados C p.Tamb = 24; % grados C p.tau = 0.80; % s^2 p.alpha = 1.10; % s p.lambda = 1.10; % s^(-1) p.dT = 0.5; % K: semiancho de la banda terminal
% Y = [P; T; omega_1; omega_2], con omega_2 = d(omega_1)/dt. tspan = [0, 20]; % s Y0 = [50; 68; 0.20; 0]; Nval = [50, 100, 200, 400, 800]; senal = @(t) 0.20 + 0.65*(1 - exp(-p.lambda.*t)); f = @(t,Y) modelo_pvi(t,Y,p);
fprintf('PVI: Y0 = [%.1f; %.1f; %.2f; %.1f]. Horizonte: [%.1f, %.1f] s.\n', ... Y0(1),Y0(2),Y0(3),Y0(4),tspan(1),tspan(2));

% b) PRUEBAS DE LA FUNCION GENERAL rk4_sistema
% La implementacion completa figura entre las funciones locales del final.
% Prueba autonoma de dimension 2: y'' + y = 0.
[tAuto,YAuto] = rk4_sistema(@(t,y) [y(2); -y(1)], [0,1], [1;0], 100);
errorAuto = norm(YAuto(end,:)' - [cos(1); -sin(1)],inf);
assert(errorAuto < 1e-7, 'No se supero la prueba autonoma de RK4.');

% Prueba no autonoma de dimension 1: y' = t, y(0)=0; y(2)=2.
[tNoAuto,YNoAuto] = rk4_sistema(@(t,y) t, [0,2], 0, 10);
errorNoAuto = abs(YNoAuto(end,1)-2);
assert(errorNoAuto < 1e-10, 'No se supero la prueba no autonoma de RK4.');
assert(iscolumn(tAuto) && size(YAuto,1)==numel(tAuto));
assert(iscolumn(tNoAuto) && size(YNoAuto,2)==1);
fprintf('Pruebas RK4 correctas: error autonomo %.3e, no autonomo %.3e.\n', ...
    errorAuto,errorNoAuto);

% c) SIMULACION, REFINAMIENTO Y VERIFICACION DEL DOMINIO P>0
mallas = cell(numel(Nval),1);
soluciones = cell(numel(Nval),1);
minP_nodos = zeros(numel(Nval),1);
minP_etapas = zeros(numel(Nval),1);
pasos = (tspan(2)-tspan(1))./Nval(:);

for a = 1:numel(Nval)
    [mallas{a},soluciones{a}] = rk4_sistema(f,tspan,Y0,Nval(a));
    minP_nodos(a) = min(soluciones{a}(:,1));
    minP_etapas(a) = presion_min_etapas(f,mallas{a},soluciones{a});
    assert(minP_nodos(a)>0 && minP_etapas(a)>0, ...
        'Se detecto una presion no positiva: N = %d.',Nval(a));
end

tablaDominio = table(Nval(:), minP_nodos, minP_etapas, ...
    'VariableNames',{'N','Pmin_nodos_kPa','Pmin_etapas_kPa'});
disp('Comprobacion de presion positiva (kPa):');
disp(tablaDominio);

% Comparacion de N=200 y N=800; cada panel tiene unidades y leyenda.
i200 = find(Nval==200,1);
i800 = find(Nval==800,1);
t200 = mallas{i200}; y200 = soluciones{i200};
t800 = mallas{i800}; y800 = soluciones{i800};

figure('Name','RC02 - Trayectorias con RK4','Color','w');
subplot(3,1,1);
plot(t200,y200(:,1),'b--','LineWidth',1.3); hold on;
plot(t800,y800(:,1),'r-','LineWidth',1.2);
grid on; xlabel('Tiempo (s)'); ylabel('P (kPa)');
title('Presion en la camara'); legend('N=200','N=800','Location','best');

subplot(3,1,2);
plot(t200,y200(:,2),'b--','LineWidth',1.3); hold on;
plot(t800,y800(:,2),'r-','LineWidth',1.2);
plot([tspan(1),tspan(2)],[42,42],'k:','LineWidth',1.0);
grid on; xlabel('Tiempo (s)'); ylabel('T (grados C)');
title('Temperatura media'); legend('N=200','N=800','Umbral de 42 C','Location','best');

subplot(3,1,3);
plot(t200,y200(:,3),'b--','LineWidth',1.3); hold on;
plot(t800,y800(:,3),'r-','LineWidth',1.2);
tfino = linspace(tspan(1),tspan(2),1000);
plot(tfino,senal(tfino),'Color',[0.25,0.55,0.25],'LineWidth',1.1);
plot([tspan(1),tspan(2)],[0.70,0.70],'k:','LineWidth',1.0);
grid on; xlabel('Tiempo (s)'); ylabel('omega (adimensional)');
title('Regimen real de la electrobomba y senal de mando');
legend('N=200','N=800','s(t)','Umbral omega=0.70','Location','southeast','NumColumns',2);

% Cuanto cambian las curvas al refinar: N=200 contra N=800.
% Cada nodo de N=200 coincide con uno de cada 4 nodos de N=800.
comun800 = y800(1:4:end,:);
difMax = max(abs(comun800 - y200),[],1);
fprintf('Diferencia maxima N=200 vs N=800 en los nodos comunes:\n');
fprintf('  P: %.3e kPa | T: %.3e C | omega: %.3e\n',difMax(1),difMax(2),difMax(3));
[wMax,iwMax] = max(y800(:,3));
fprintf('omega llega a un maximo de %.4f en t = %.3f s (s_inf = 0.85).\n', ...
    wMax,t800(iwMax));

% d) ESTIMACION NODAL DE LOS CUATRO EVENTOS
% Columnas: [tT42, tOmega70, tPmin, Pmin, tEstT].
eventos = nan(numel(Nval),5);
for a = 1:numel(Nval)
    eventos(a,:) = eventos_malla(mallas{a},soluciones{a},p.dT);
end

tablaEventos = array2table([Nval(:),pasos,eventos], ...
    'VariableNames',{'N','h_s','tT42_s','tOmega70_s', ...
                     'tPmin_s','Pmin_kPa','tEstT_s'});
disp('Eventos RK4: los tiempos y h estan en s; Pmin esta en kPa.');
disp(tablaEventos);

% Para la tabla se conserva el minimo discreto, incluidos ambos extremos.
% Una parabola por tres nodos solo se explica teoricamente: no se usa
% para modificar los resultados exigidos en la tabla.

% e) REFERENCIA ode45, VERIFICACION DE ESTABILIDAD Y ERRORES
% ode45 se utiliza solo en la validacion; las cinco mallas anteriores son RK4.
% Segunda corrida: tolerancias de ode45 Y tolerancia de fzero mas estrictas.
%                                 RelTol AbsTol  TolX(fzero)
ref10 = eventos_referencia(f,p,tspan,Y0,1e-10,1e-12,1e-12);
ref12 = eventos_referencia(f,p,tspan,Y0,1e-12,1e-14,1e-14);
variacionRef = abs(ref10-ref12);

% Se comprueba la estabilidad de los cuatro tiempos y del valor de Pmin.
assert(all(variacionRef([1,2,3,5]) < 1e-6) && variacionRef(4)<1e-5, ...
    'La referencia no es suficientemente estable. Refinar tolerancias.');

nombresRef = {'tT42_s'; 'tOmega70_s'; 'tPmin_s'; 'Pmin_kPa'; 'tEstT_s'};
tablaRef = table(nombresRef,ref10(:),ref12(:),variacionRef(:), ...
    'VariableNames',{'Magnitud','Referencia_1','Referencia_2','Variacion_abs'});
disp('Comparacion de referencias (ode45 y raices refinadas con fzero):');
disp(tablaRef);

% Errores absolutos: columnas [ET42, Eomega70, EtPmin, EPmin, EestT].
errores = abs(eventos - repmat(ref12,numel(Nval),1));
tablaErrores = array2table([Nval(:),pasos,errores], ...
    'VariableNames',{'N','h_s','E_T42_s','E_omega70_s', ...
                     'E_tPmin_s','E_Pmin_kPa','E_estT_s'});
disp('Tabla de los cinco errores absolutos:');
disp(tablaErrores);

% La referencia debe variar mucho menos que el menor error de RK4.
menorErrorRK4 = min(errores,[],1);
disp('Variacion de la referencia / menor error RK4 (debe ser << 1):');
disp(variacionRef./menorErrorRK4);
if any(variacionRef > 0.1*menorErrorRK4)
    warning('La referencia varia demasiado frente al error de RK4.');
end

% Se grafican exclusivamente errores positivos; no se fabrican valores.
figure('Name','RC02 - Errores de eventos','Color','w');
subplot(1,2,1); hold on;
indicesTiempos = [1,2,3,5];
etiquetasTiempos = {'T=42 C','omega=0.70','Instante de Pmin','Banda terminal'};
for k = 1:4
    j = indicesTiempos(k);
    valido = isfinite(errores(:,j)) & errores(:,j)>0;
    if any(valido)
        loglog(pasos(valido),errores(valido,j),'-o', ...
            'LineWidth',1.1,'DisplayName',etiquetasTiempos{k});
    end
    if any(~valido)
        fprintf('Serie %s: %d errores nulos o no disponibles sin graficar.\n', ...
            etiquetasTiempos{k},sum(~valido));
    end
end
set(gca,'XScale','log','YScale','log');   % eje loglog (hold on lo dejaba lineal)
grid on; xlabel('h (s)'); ylabel('Error absoluto de tiempo (s)');
title('Errores de tiempo frente a h'); legend('Location','best');

subplot(1,2,2);
validoP = isfinite(errores(:,4)) & errores(:,4)>0;
if any(validoP)
    loglog(pasos(validoP),errores(validoP,4),'-o', ...
        'LineWidth',1.3,'DisplayName','Error del valor Pmin');
    legend('Location','best');
end
if any(~validoP)
    fprintf('Error de Pmin: %d valores nulos o no disponibles sin graficar.\n', ...
        sum(~validoP));
end
grid on; xlabel('h (s)'); ylabel('Error absoluto de presion (kPa)');
title('Error del minimo de presion frente a h');

% f) CRITERIO DE ACEPTACION Y ELECCION DE LA MALLA
% Son tolerancias que fijamos para esta actividad, no normas industriales.
% 30 ms = 0.15 % del horizonte (20 s); menor que la escala del transitorio.
% 0.01 kPa = 0.02 % de P(0) y ~0.25 % de la caida inicial de presion (~4 kPa).
tolTiempo = 0.03;  % s
tolPresion = 0.01; % kPa
cumple = all(errores(:,[1,2,3,5])<=tolTiempo,2) & ...
         errores(:,4)<=tolPresion;
tablaCriterio = table(Nval(:),cumple, ...
    'VariableNames',{'N','Cumple_5_errores'});
disp('Verificacion conjunta de tolerancias:');
disp(tablaCriterio);

% Sensibilidad: que malla bastaria con tolerancias mas flojas (0.1 s, 0.05 kPa)?
tolTiempoFloja = 0.10;  % s
tolPresionFloja = 0.05; % kPa
cumpleFloja = all(errores(:,[1,2,3,5])<=tolTiempoFloja,2) & ...
              errores(:,4)<=tolPresionFloja;
iFloja = find(cumpleFloja,1,'first');
if ~isempty(iFloja)
    fprintf('Con tolerancias mas flojas bastaria N=%d.\n',Nval(iFloja));
end

indiceElegido = find(cumple,1,'first');
if isempty(indiceElegido)
    fprintf('Ninguna malla cumple: ampliar N a 1600, 3200, ... y reevaluar.\n');
else
    Nelegido = Nval(indiceElegido);
    fprintf('Malla seleccionada: N=%d, h=%.6f s.\n', ...
        Nelegido,pasos(indiceElegido));
    fprintf('Mayor error temporal: %.9f s; error de Pmin: %.9f kPa.\n', ...
        max(errores(indiceElegido,[1,2,3,5])),errores(indiceElegido,4));
end

% La banda terminal no prueba equilibrio: evaluar la pendiente al final.
estadoFinal = soluciones{end}(end,:)';
pendienteFinal = f(tspan(2),estadoFinal);
fprintf('En t=20 s: T=%.9f C, dT/dt=%.9f C/s.\n', ...
    estadoFinal(2),pendienteFinal(2));

% FUNCIONES LOCALES: TODAS LAS FUNCIONES PROPIAS ESTAN AL FINAL DEL MLX.
function dY = modelo_pvi(t,Y,p)
    % Primera componente: presion (kPa). El modelo exige P>0.
    Y = Y(:);
    if numel(Y)~=4 || ~isfinite(Y(1)) || Y(1)<=0
        error('modelo_pvi:dominio', ...
            'Se encontro P<=0 o estado invalido en t=%.16g s.',t);
    end
    P = Y(1); T = Y(2); w1 = Y(3); w2 = Y(4);
    s = 0.20 + 0.65*(1-exp(-p.lambda*t));
    dP = (p.Qmax*w1 - p.Kv*sqrt(P))/p.Ch;
    dT = (p.Qmax*w1/(p.Ch*P))*(p.Tin-T) + ...
         (p.Qgen-p.UA*(T-p.Tamb))/(p.rho*p.cp*p.Ch*P);
    dw1 = w2;
    dw2 = (s - p.alpha*w2 - w1)/p.tau;
    dY = [dP; dT; dw1; dw2];
end

function [t,Y] = rk4_sistema(f,tspan,Y0,N)
    % RK4 clasico, dimension arbitraria, tiempo autonomo o no autonomo.
    if ~(isnumeric(N) && isscalar(N) && N>=1 && N==floor(N))
        error('rk4_sistema:N','N debe ser un entero positivo.');
    end
    if numel(tspan)~=2 || ~(tspan(2)>tspan(1))
        error('rk4_sistema:tspan','tspan debe ser [t0,tf] con tf>t0.');
    end
    Y0 = Y0(:);
    m = numel(Y0);
    h = (tspan(2)-tspan(1))/N;
    t = tspan(1) + (0:N)'*h;
    Y = zeros(N+1,m);
    Y(1,:) = Y0';
    for i = 1:N
        yi = Y(i,:)';
        ti = t(i);
        k1 = f(ti,yi);                     k1 = k1(:);
        k2 = f(ti+h/2,yi+(h/2)*k1);       k2 = k2(:);
        k3 = f(ti+h/2,yi+(h/2)*k2);       k3 = k3(:);
        k4 = f(ti+h,yi+h*k3);             k4 = k4(:);
        if any([numel(k1),numel(k2),numel(k3),numel(k4)]~=m)
            error('rk4_sistema:dimension','f debe devolver m componentes.');
        end
        ysig = yi+(h/6)*(k1+2*k2+2*k3+k4);
        if any(~isfinite(ysig))
            error('rk4_sistema:noFinito','Estado no finito en la iteracion %d.',i);
        end
        Y(i+1,:) = ysig';
    end
end

function minimo = presion_min_etapas(f,t,Y)
    % Reconstruye estados internos k2, k3, k4 y revisa su presion.
    h = t(2)-t(1);
    minimo = min(Y(:,1));
    for i = 1:numel(t)-1
        yi = Y(i,:)'; ti = t(i);
        k1 = f(ti,yi);
        y2 = yi+(h/2)*k1;
        k2 = f(ti+h/2,y2);
        y3 = yi+(h/2)*k2;
        k3 = f(ti+h/2,y3);
        y4 = yi+h*k3;
        f(ti+h,y4); % Comprobacion explicita de dominio en la cuarta etapa.
        minimo = min([minimo,y2(1),y3(1),y4(1)]);
    end
    if minimo<=0
        error('presion_min_etapas:dominio','Una etapa RK4 sale de P>0.');
    end
end

function tiempo = primer_cruce(t,y,umbral,direccion)
    % direccion = -1: cruce descendente; +1: ascendente.
    % Cuenta un nodo exactamente igual al umbral una sola vez.
    t = t(:); y = y(:); d = y-umbral; n = numel(t);
    if direccion~=1 && direccion~=-1
        error('primer_cruce:direccion','Direccion debe ser +1 o -1.');
    end
    tiempo = NaN;
    for i = 1:n
        if d(i)==0
            if (i>1 && d(i-1)==0) || (i<n && d(i+1)==0)
                % Un tramo de nodos consecutivos en el umbral es ambiguo.
                continue;
            end
            iz = find(d(1:i-1)~=0,1,'last');
            der = find(d(i+1:end)~=0,1,'first');
            if ~isempty(der), der = i+der; end
            if isempty(iz) && isempty(der)
                % Trayectoria identicamente igual al umbral: sin cruce unico.
                return;
            elseif isempty(iz)
                esCruce = ~isempty(der) && sign(d(der))==direccion;
            elseif isempty(der)
                esCruce = sign(d(iz))==-direccion;
            else
                esCruce = sign(d(iz))==-direccion && ...
                           sign(d(der))==direccion;
            end
            if esCruce
                tiempo = t(i);
                return;
            end
        end
        if i<n && d(i)*d(i+1)<0 && sign(d(i))==-direccion
            tiempo = t(i)+(umbral-y(i))*(t(i+1)-t(i))/(y(i+1)-y(i));
            return;
        end
    end
end

function v = eventos_malla(t,Y,dT)
    tT42 = primer_cruce(t,Y(:,2),42,-1);
    tW70 = primer_cruce(t,Y(:,3),0.70,+1);
    [Pmin,imin] = min(Y(:,1)); % min devuelve el primer indice en un empate.
    tPmin = t(imin);
    fuera = find(abs(Y(:,2)-Y(end,2))>dT,1,'last');
    if isempty(fuera)
        testT = t(1);
    else
        testT = t(fuera+1);
    end
    v = [tT42,tW70,tPmin,Pmin,testT];
end

function v = eventos_referencia(f,p,tspan,Y0,RelTol,AbsTol,tolRaiz)
    % Referencia con solucion densa; exploracion fina y raices acotadas.
    optOde = odeset('RelTol',RelTol,'AbsTol',AbsTol);
    sol = ode45(f,tspan,Y0,optOde);
    exploracion = linspace(tspan(1),tspan(2),50001);
    yy = deval(sol,exploracion);
    optRaiz = optimset('TolX',tolRaiz,'Display','off');
    if any(yy(1,:)<=0)
        error('eventos_referencia:dominio','Presion de referencia no positiva.');
    end

    % Primer cruce descendente de T=42.
    candT = find(yy(2,1:end-1)>42 & yy(2,2:end)<=42);
    if isempty(candT)
        tT42 = NaN;
    else
        j = candT(1);
        tT42 = fzero(@(z) temperatura_ref(z,sol)-42, ...
            exploracion([j,j+1]),optRaiz);
    end

    % Primer cruce ascendente del regimen real omega=0.70.
    candW = find(yy(3,1:end-1)<0.70 & yy(3,2:end)>=0.70);
    if isempty(candW)
        tW70 = NaN;
    else
        j = candW(1);
        tW70 = fzero(@(z) velocidad_ref(z,sol)-0.70, ...
            exploracion([j,j+1]),optRaiz);
    end

    % Minimo global: candidatos P'=0 que pasan de - a + y los extremos.
    gP = (p.Qmax*yy(3,:)-p.Kv*sqrt(yy(1,:)))/p.Ch;
    candP = find(gP(1:end-1)<0 & gP(2:end)>0);
    tCandidatos = [tspan(1),tspan(2)];
    for k = 1:numel(candP)
        j = candP(k);
        tRaiz = fzero(@(z) derivada_presion_ref(z,sol,p), ...
            exploracion([j,j+1]),optRaiz);
        tCandidatos(end+1) = tRaiz; %#ok<AGROW>
    end
    presiones = zeros(size(tCandidatos));
    for k = 1:numel(tCandidatos)
        estado = deval(sol,tCandidatos(k));
        presiones(k) = estado(1);
    end
    [Pmin,imin] = min(presiones);
    tPmin = tCandidatos(imin);

    % Ultima entrada en |T(t)-T(tf)|<=dT: ambas fronteras estan en abs.
    yf = deval(sol,tspan(2));
    Tf = yf(2);
    gT = abs(yy(2,:)-Tf)-p.dT;
    ultimoFuera = find(gT>0,1,'last');
    if isempty(ultimoFuera)
        testT = tspan(1);
    else
        if ultimoFuera==numel(exploracion)
            error('eventos_referencia:banda','El final debe estar en la banda.');
        end
        testT = fzero(@(z) abs(temperatura_ref(z,sol)-Tf)-p.dT, ...
            exploracion([ultimoFuera,ultimoFuera+1]),optRaiz);
    end
    posterior = deval(sol,linspace(testT,tspan(2),10001));
    assert(all(abs(posterior(2,:)-Tf)<=p.dT+1e-8), ...
        'La trayectoria de referencia abandona la banda terminal.');
    v = [tT42,tW70,tPmin,Pmin,testT];
end

function T = temperatura_ref(t,sol)
    z = deval(sol,t);
    T = z(2);
end

function w = velocidad_ref(t,sol)
    z = deval(sol,t);
    w = z(3);
end

function dp = derivada_presion_ref(t,sol,p)
    z = deval(sol,t);
    dp = (p.Qmax*z(3)-p.Kv*sqrt(z(1)))/p.Ch;
end
